def cache_sim(capacity, ttl, ops):
    cache = {}  # key -> (value, write_time)
    access_order = []  # list of keys in order of access (most recent at end)
    results = []

    def is_expired(key, current_time):
        if key not in cache:
            return True
        value, write_time = cache[key]
        return current_time >= write_time + ttl

    def remove_expired(current_time):
        expired_keys = [k for k in cache if is_expired(k, current_time)]
        for k in expired_keys:
            del cache[k]
            if k in access_order:
                access_order.remove(k)

    def mark_accessed(key):
        if key in access_order:
            access_order.remove(key)
        access_order.append(key)

    for op in ops:
        if op[0] == 'put':
            _, t, key, value = op
            remove_expired(t)

            # If key is new and cache is full, evict LRU
            if key not in cache and len(cache) >= capacity:
                lru_key = access_order.pop(0)
                del cache[lru_key]

            # Store the value with write time
            cache[key] = (value, t)
            mark_accessed(key)

        elif op[0] == 'get':
            _, t, key = op
            remove_expired(t)

            if key in cache:
                value, write_time = cache[key]
                results.append(value)
                mark_accessed(key)
            else:
                results.append(-1)

    return results

